package com.uthmani.quran.data.db

import androidx.room.ColumnInfo
import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * Room entities.
 *
 * IMPORTANT: the prepackaged database (assets/databases/quran.db) is generated by
 * scripts/build_db.py and MUST match these entity definitions exactly
 * (column names, types, NOT NULL, primary keys, index names).
 */

@Entity(tableName = "surahs")
data class SurahEntity(
    @PrimaryKey
    @ColumnInfo(name = "number") val number: Int,
    @ColumnInfo(name = "name_arabic") val nameArabic: String,
    @ColumnInfo(name = "name_persian") val namePersian: String,
    @ColumnInfo(name = "ayah_count") val ayahCount: Int,
    /** "Meccan" | "Medinan" (as provided by Tanzil metadata). */
    @ColumnInfo(name = "revelation_type") val revelationType: String,
    @ColumnInfo(name = "revelation_order") val revelationOrder: Int,
)

@Entity(
    tableName = "ayahs",
    primaryKeys = ["surah", "ayah"],
    indices = [Index(value = ["text_simple"])],
)
data class AyahEntity(
    @ColumnInfo(name = "surah") val surah: Int,
    @ColumnInfo(name = "ayah") val ayah: Int,
    /** VERBATIM Tanzil Uthmani text — never modified. */
    @ColumnInfo(name = "text") val text: String,
    /** Search-only normalization of [text] (see QuranTextNormalizer). */
    @ColumnInfo(name = "text_simple") val textSimple: String,
)

@Entity(
    tableName = "bookmarks",
    indices = [Index(value = ["surah", "ayah"], unique = true)],
)
data class BookmarkEntity(
    @PrimaryKey(autoGenerate = true)
    @ColumnInfo(name = "id") val id: Long = 0,
    @ColumnInfo(name = "surah") val surah: Int,
    @ColumnInfo(name = "ayah") val ayah: Int,
    @ColumnInfo(name = "created_at") val createdAt: Long,
)

/**
 * Future-proofing layer for translations (currently empty, no UI).
 * A translation pack can be inserted later with (translator, surah, ayah, text)
 * without touching the Quran text tables.
 */
@Entity(
    tableName = "translations",
    primaryKeys = ["translator", "surah", "ayah"],
)
data class TranslationEntity(
    @ColumnInfo(name = "translator") val translator: String,
    @ColumnInfo(name = "surah") val surah: Int,
    @ColumnInfo(name = "ayah") val ayah: Int,
    @ColumnInfo(name = "text") val text: String,
)

@Entity(tableName = "juzs")
data class JuzEntity(
    @PrimaryKey
    @ColumnInfo(name = "number") val number: Int,
    @ColumnInfo(name = "surah") val surah: Int,
    @ColumnInfo(name = "ayah") val ayah: Int,
)

/** Key/value metadata; carries the Tanzil copyright notice with the database file. */
@Entity(tableName = "meta")
data class MetaEntity(
    @PrimaryKey
    @ColumnInfo(name = "key") val key: String,
    @ColumnInfo(name = "value") val value: String,
)

/** Projection row for bookmark list (not an entity). */
data class BookmarkRow(
    val surah: Int,
    val ayah: Int,
    val createdAt: Long,
    val surahNamePersian: String,
    val surahNameArabic: String,
    val ayahText: String,
)

/** Projection row for search results (not an entity). */
data class SearchRow(
    val surah: Int,
    val ayah: Int,
    val text: String,
    val namePersian: String,
    val nameArabic: String,
)
